css+='\n::selection{background:#d1e9e5;color:#123c37}input,textarea{caret-color:var(--accent)}table,.score,.summary{font-variant-numeric:tabular-nums}a{text-underline-offset:3px}.decision select{display:block;padding:8px;border:1px solid var(--line);border-radius:6px;margin:6px 0 14px;width:100%}progress.progress{display:block;width:100%;accent-color:var(--accent)}\n'
css+='@media(max-width:720px){.table-scroll{overflow:visible}table,tbody,tr,td{display:block}thead{display:none}tbody tr{display:grid;grid-template-columns:1fr 1fr;gap:14px;border-bottom:1px solid var(--line);padding:20px 0}td{padding:0;border:0;min-width:0!important}td:first-child{grid-column:1/-1}td:nth-child(3) .score{font-size:22px}td:nth-child(4):before{content:"Value";display:block;color:var(--muted);font-size:12px}td:nth-child(5):before{content:"Deadline";display:block;color:var(--muted);font-size:12px}td:nth-child(6):before{content:"Founder work";display:block;color:var(--muted);font-size:12px}.detail-grid{display:flex;flex-direction:column;gap:0}.detail-grid>div{display:contents}.detail-grid>div:first-child>section:nth-child(1){order:1}.detail-grid>div:first-child>section:nth-child(2){order:2}.detail-grid>div:first-child>section:nth-child(3){order:4}.detail-grid>div:first-child>section:nth-child(4){order:7}.detail-grid>div:last-child>section:nth-child(1){order:0}.detail-grid>div:last-child>section:nth-child(2){order:3}.detail-grid>div:last-child>section:nth-child(3){order:5}}\n'
