p=ROOT/'founder_os/ui/app.js';text=p.read_text(encoding='utf-8');text=text.replace("['pitch_competition','grant','accelerator','incubator','startup_program','credits','fellowship','award']","[...new Set(['pitch_competition','grant','accelerator','incubator','startup_program','credits','credits_grant','fellowship','award',...dash.opportunities.map(d=>d.data.opportunity_type)])]")
text=text.replace("${E(dash.settings.runner.status)} · ${E(dash.settings.runner.type)}","${dash.settings.runner.status==='connected'?'Automatic research connected':'Automatic research not connected'}")
